def calculate_stats_for_students(test_results):
    """
    Calculate the average test score and the standard deviation for each student.

    Parameters:
    test_results (list of dict): Each dictionary contains test results for a
        student. Recognized keys are:
        - student id key: 'student_id' (also accepts 'id' or 'student')
        - scores key: 'scores' (a list of numbers) (also accepts 'test_scores')
        Alternatively, each dictionary may be a single record with a 'score'
        key (also accepts 'test_score'), in which case results are grouped by
        student id across all records.

    Returns:
    dict: keys are student IDs and values are tuples (average_score, std_dev)
          for that student.

    Raises:
    ValueError: if a student in test_results does not have any test scores.

    Requirements:
    - pandas
    - numpy

    Example:
    >>> results = [
    ...     {'student_id': 1, 'scores': [90, 80, 70]},
    ...     {'student_id': 2, 'scores': [100, 90]},
    ... ]
    >>> calculate_stats_for_students(results)
    {1: (80.0, 8.16496580927726), 2: (95.0, 5.0)}
    """
    if not isinstance(test_results, (list, tuple)):
        raise ValueError("test_results must be a list of dictionaries")

    id_keys = ('student_id', 'id', 'student')
    scores_keys = ('scores', 'test_scores')
    score_keys = ('score', 'test_score')

    def _get_first(d, keys):
        for k in keys:
            if k in d:
                return d[k]
        return None

    # Group scores per student id
    grouped = {}

    for record in test_results:
        if not isinstance(record, dict):
            raise ValueError("Each test result must be a dictionary")

        student_id = _get_first(record, id_keys)
        if student_id is None:
            raise ValueError("Each test result must contain a student id key")

        if student_id not in grouped:
            grouped[student_id] = []

        scores = _get_first(record, scores_keys)
        if scores is not None:
            if scores is None or (hasattr(scores, '__len__') and len(scores) == 0):
                grouped[student_id].extend([])
            else:
                grouped[student_id].extend(list(scores))
        else:
            single = _get_first(record, score_keys)
            if single is not None:
                grouped[student_id].append(single)

    result = {}
    for student_id, scores in grouped.items():
        if len(scores) == 0:
            raise ValueError(
                f"Student {student_id} does not have any test scores"
            )
        arr = np.asarray(scores, dtype=float)
        avg = float(np.mean(arr))
        std = float(np.std(arr))
        result[student_id] = (avg, std)

    return result


